// Pure game rules. No DOM, timers, audio or network dependencies.
export const SIZE = 12;
export const ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
const WEIGHTED = 'AAAAAAAABCDEEEEEEEEEEEFGHHIIIIIIJKLMNNOOOOOPRRRRSSSSSTTTTTTTUUUVWY';
