export function seededRandom(seed) { let n=seed>>>0; return () => { n+=0x6D2B79F5; let t=n; t=Math.imul(t^(t>>>15),t|1); t^=t+Math.imul(t^(t>>>7),t|61); return ((t^(t>>>14))>>>0)/4294967296; }; }
export function shuffle(items,rng=Math.random) { const a=[...items]; for(let i=a.length-1;i>0;i--){const j=Math.floor(rng()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a; }
const pick=(items,rng)=>items[Math.floor(rng()*items.length)];
const indices=(row,col,length,dir)=>Array.from({length},(_,i)=>(row+(dir==='down'?i:0))*SIZE+col+(dir==='across'?i:0));

// Enumerate every contiguous dictionary word containing the new letter.
// Other gaps stop the segment. No wrapping, backwards words or diagonals.
export function findWords(board,index,letter,dictionary) {
  if(board[index]!==null || !/^[A-Z]$/.test(letter))return [];
  const row=Math.floor(index/SIZE),col=index%SIZE, matches=[];
  for(const direction of ['across','down']) {
    const line=Array.from({length:SIZE},(_,i)=>direction==='across'?row*SIZE+i:i*SIZE+col);
    const pivot=direction==='across'?col:row;
    let lo=pivot,hi=pivot;
    while(lo>0&&board[line[lo-1]]!==null)lo--;
    while(hi<SIZE-1&&board[line[hi+1]]!==null)hi++;
    for(let start=lo;start<=pivot;start++) {
      let word='';
      for(let end=start;end<=hi;end++) {
        word+=end===pivot?letter:board[line[end]];
        if(end>=pivot&&word.length>=3&&dictionary.has(word))matches.push({word,direction,cells:line.slice(start,end+1),key:`${direction}:${line[start]}:${word}`});
      }
    }
  }
  return matches;
}
export function solutionsFor(board,index,dictionary) {
  const result=new Map();
  if(board[index]!==null)return result;
  for(const letter of ALPHABET){const words=findWords(board,index,letter,dictionary);if(words.length)result.set(letter,words);}
  return result;
}
export function allSolutions(board,dictionary) {
  const result=new Map();
  for(let i=0;i<board.length;i++)if(board[i]===null)result.set(i,solutionsFor(board,i,dictionary));
  return result;
}
export const GAP_COUNT=15;
export const RACK_SIZE=16;
export function availableMoves(state) {
  const rack=new Set(state.rack.filter((_,slot)=>!state.rackUsed[slot])),moves=[];
  for(const [index,options] of state.options)for(const [letter,words] of options)if(rack.has(letter))moves.push({index,letter,words});
  return moves;
}
export function canAnswer(state,index=state.active) {return state.rack.some((letter,slot)=>!state.rackUsed[slot]&&state.options.get(index)?.has(letter));}
export function orderedWords(words) {return [...words].sort((a,b)=>a.word.length-b.word.length||a.word.localeCompare(b.word)||a.key.localeCompare(b.key));}
export function rewardFor(misses,words,automatic=false) {
  if(automatic)return {colour:'red',points:0};
  if(words.length>1)return {colour:'gold',points:5};
  return misses===0?{colour:'green',points:2}:{colour:'amber',points:1};
}
// Fifteen gaps have fourteen transitions, so interpolate to reach 15 exactly.
export function timeAllowance(ordinal) {return 30-Math.round((Math.min(15,Math.max(1,ordinal))-1)*15/14);}
// Only overall active thinking time is used. One bonus point per 15 seconds
// saved against the board budget, capped by manually completed gaps.
export function speedBonus(elapsedMs,manualSolved,budgetSeconds=337) {
  return Math.max(0,Math.min(manualSolved,Math.floor((budgetSeconds-Math.max(0,elapsedMs)/1000)/15)));
}

// Match each unresolved gap to a different unused rack slot. A complete
// matching is a constructive solution: every word is already valid independently
// of other gaps, so filling another matched gap cannot destroy it.
export function assignRack(board,rack,rackUsed,dictionary,options=allSolutions(board,dictionary),preferred=new Map()) {
  const slots=rack.map((_,i)=>i).filter(i=>!rackUsed[i]);
  const gaps=[...options.keys()].sort((a,b)=>options.get(a).size-options.get(b).size);
  const owners=new Map();
  function assign(id,visited){
    const candidates=slots.filter(slot=>options.get(id).has(rack[slot])).sort((a,b)=>(rack[a]===preferred.get(id)?-1:0)-(rack[b]===preferred.get(id)?-1:0));
    for(const slot of candidates){
      if(visited.has(slot))continue;visited.add(slot);
      if(!owners.has(slot)||assign(owners.get(slot),visited)){owners.set(slot,id);return true;}
    }
    return false;
  }
  for(const id of gaps)if(!assign(id,new Set()))return null;
  return new Map([...owners].map(([slot,id])=>[id,slot]));
}

function generateLayout(count,dictionary,rng) {
  const board=Array(SIZE*SIZE).fill(null), used=Array(SIZE*SIZE).fill(0), holes=new Set(), planted=[];
  const pool=shuffle(COMMON.filter(w=>dictionary.has(w)&&w.length>=3&&w.length<=(count===20?6:8)),rng);
  const crossPool=pool.filter(w=>w.length>=4&&w.length<=6);
  const h=pick(crossPool,rng);
  const hPos=1+Math.floor(rng()*(h.length-2));
  const pairs=crossPool.flatMap(w=>w===h?[]:[...w].flatMap((l,i)=>l===h[hPos]&&i>0&&i<w.length-1?[{word:w,pos:i}]:[]));
  if(!pairs.length)return null;
  const v=pick(pairs,rng);
  const row=v.pos+Math.floor(rng()*(SIZE-v.word.length+1));
  const col=hPos+Math.floor(rng()*(SIZE-h.length+1));
  const shared=row*SIZE+col;
  function put(word,ids,gaps,type='normal') {ids.forEach((id,i)=>{board[id]=word[i];used[id]++;});gaps.forEach(id=>holes.add(id));planted.push({word,cells:ids,gaps,type});}
  put(h,indices(row,col-hPos,h.length,'across'),[shared],'double');
  put(v.word,indices(row-v.pos,col,v.word.length,'down'),[shared],'double');
  const chosen=new Set(planted.map(p=>p.word));
  for(let n=2;n<count;n++) {
    let best=null;
    for(const word of shuffle(pool,rng)) {
      if(chosen.has(word))continue;
      const spots=[];
      for(const dir of shuffle(['across','down'],rng))for(let r=0;r<SIZE-(dir==='down'?word.length-1:0);r++)for(let c=0;c<SIZE-(dir==='across'?word.length-1:0);c++){
        const ids=indices(r,c,word.length,dir);
        if(ids.some((id,i)=>holes.has(id)||(used[id]&&board[id]!==word[i])))continue;
        const free=ids.filter(id=>used[id]===0);
        if(free.length<Math.max(2,word.length-2))continue;
        spots.push({word,ids,free});
      }
      if(spots.length){best=pick(spots,rng);break;}
    }
    if(!best)return null;
    put(best.word,best.ids,[pick(best.free,rng)]);chosen.add(best.word);
  }
  for(let i=0;i<board.length;i++)if(!used[i])board[i]=pick(WEIGHTED,rng);
  const answers=new Map([...holes].map(id=>[id,board[id]]));
  holes.forEach(id=>board[id]=null);
  return {board,planted,answers,shared};
}
export function createRound({dictionary,rng=Math.random,score=0,totalWords=0,round=1}={}) {
  let layout;
  for(let attempt=0;attempt<30&&!layout;attempt++)layout=generateLayout(GAP_COUNT+1,dictionary,rng);
  if(!layout)throw new Error('Could not prepare a board. Please try again.');
  const options=allSolutions(layout.board,dictionary),order=shuffle([...layout.answers.keys()],rng);
  const rack=shuffle([...layout.answers.values(),pick(WEIGHTED,rng)],rng);
  const state={...layout,options,rack,rackUsed:Array(RACK_SIZE).fill(null),order,active:order[0],gaps:Object.fromEntries(order.map((id,i)=>[id,{misses:0,shownMisses:0,visits:0,reward:null,ordinal:i+1,allowance:timeAllowance(i+1)}])),found:[],score,totalWords,round,roundPoints:0,roundWords:0,filled:0,manualSolved:0,automaticSolved:0,ended:false,bonusAwarded:false};
  state.gaps[state.active].visits=1;
  return state;
}
function nextGap(state,previous) {
  const at=state.order.indexOf(previous);
  for(let offset=1;offset<=state.order.length;offset++){
    const id=state.order[(at+offset)%state.order.length];
    if(state.board[id]===null){state.active=id;state.gaps[id].visits++;state.gaps[id].shownMisses=state.gaps[id].misses;return;}
  }
  state.active=null;
}
function fill(state,index,slot,words,automatic,dictionary,reason) {
  const gap=state.gaps[index],letter=state.rack[slot],reward=rewardFor(gap.misses,words,automatic);
  state.board[index]=letter;gap.reward=reward.colour;state.rackUsed[slot]=automatic?'automatic':'used';
  state.found.push(...words);state.score+=reward.points;state.roundPoints+=reward.points;state.totalWords+=words.length;state.roundWords+=words.length;state.filled++;
  if(automatic)state.automaticSolved++;else state.manualSolved++;
  state.options=allSolutions(state.board,dictionary);state.ended=state.options.size===0;nextGap(state,index);
  return {kind:automatic?'automatic':'correct',index,letter,slot,words:orderedWords(words),...reward,ended:state.ended,reason};
}
// Mutates one round atomically. Wrong letters keep their slot; they count as a
// missed opportunity, like a pass. Two misses always resolve the gap for zero.
export function act(state,action,dictionary) {
  if(state.ended||state.active===null)return {kind:'ignored'};
  const index=state.active,gap=state.gaps[index];
  if(!['pass','timeout','letter'].includes(action.type))return {kind:'ignored'};
  if(action.type==='letter') {
    if(!Number.isInteger(action.slot)||action.slot<0||action.slot>=state.rack.length||state.rackUsed[action.slot])return {kind:'ignored'};
    const words=findWords(state.board,index,state.rack[action.slot],dictionary);
    if(words.length){
      const trial=[...state.board],used=[...state.rackUsed];trial[index]=state.rack[action.slot];used[action.slot]='used';
      if(!assignRack(trial,state.rack,used,dictionary))return {kind:'reserved',index,slot:action.slot,letter:state.rack[action.slot],words:orderedWords(words)};
      return fill(state,index,action.slot,words,false,dictionary);
    }
  }
  gap.misses++;
  if(gap.misses>=2){
    const assignment=assignRack(state.board,state.rack,state.rackUsed,dictionary,state.options,state.answers);
    const slot=assignment?.get(index);
    if(slot===undefined)throw new Error('The remaining rack does not contain a complete solution.');
    return fill(state,index,slot,findWords(state.board,index,state.rack[slot],dictionary),true,dictionary,action.type);
  }
  nextGap(state,index);
  return {kind:action.type==='letter'?'wrong':action.type,index,slot:action.slot,penalised:true};
}
export function finishRound(state,elapsedMs) {
  if(!state.ended)return null;
  if(!state.bonusAwarded){
    const budget=Object.values(state.gaps).reduce((sum,g)=>sum+g.allowance,0);
    const bonus=speedBonus(elapsedMs,state.manualSolved,budget);
    state.summary={wordPoints:state.roundPoints,bonus,total:state.roundPoints+bonus,elapsedMs,manualSolved:state.manualSolved,automaticSolved:state.automaticSolved,words:state.roundWords};
    state.score+=bonus;state.bonusAwarded=true;
  }
  return state.summary;
}
